/**
 * Overview cards on Medusa's own list and detail pages: what needs doing,
 * from Medusa's data, with every installed integration's signals added.
 * Like the detail cards, each plugin has the widget and the first one to
 * claim the zone renders it.
 *
 * Medusa's admin API has no aggregates, so the cards read recent records
 * and count them in the browser, and say how many they read.
 */

const DAY = 86_400_000
const STALE = 5 * 60_000

type Row = Record<string, any>

const fetchJson = <T,>(path: string, query: Record<string, unknown>) =>
  sdk.client.fetch<T>(path, { query: Object.fromEntries(Object.entries(query).filter(([, v]) => v !== undefined)) })

/** Pages through a list endpoint until `max` rows. */
async function fetchAll(path: string, key: string, query: Record<string, unknown>, max: number) {
  const rows: Row[] = []
  let count = 0
  for (let offset = 0; offset < max; offset += 100) {
    const page = await fetchJson<Record<string, any>>(path, { ...query, limit: Math.min(100, max - offset), offset })
    rows.push(...(page[key] ?? []))
    count = page.count ?? rows.length
    if ((page[key] ?? []).length < 100) break
  }
  return { rows, count, capped: count > rows.length }
}

/* Settings kept per admin in the browser ------------------------------------ */

const SETTINGS_KEY = "bitshaft.overview.v1"
type CardSettings = { collapsed: Partial<Record<OverviewScope, boolean>>; lowStock: number; shelfDays: number }
const DEFAULT_SETTINGS: CardSettings = { collapsed: {}, lowStock: 5, shelfDays: 90 }

function readSettings(): CardSettings {
  try {
    return { ...DEFAULT_SETTINGS, ...JSON.parse(localStorage.getItem(SETTINGS_KEY) ?? "{}") }
  } catch {
    return DEFAULT_SETTINGS
  }
}

function useCardSettings() {
  const [settings, setSettings] = useState<CardSettings>(readSettings)
  const save = (next: CardSettings) => {
    setSettings(next)
    try {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(next))
    } catch {
      // Private mode: the settings last for this page only.
    }
  }
  return [settings, save] as const
}

/* Formatting --------------------------------------------------------------- */

function useFormat() {
  const { i18n } = useTranslation()
  const locale = toIntlLocale(i18n.language) ?? "en-US"
  return {
    money: (amount: number, currency: string) => {
      try {
        return new Intl.NumberFormat(locale, { style: "currency", currency: currency.toUpperCase() }).format(amount)
      } catch {
        return `${amount} ${currency.toUpperCase()}`
      }
    },
    relative: (value: string) => {
      const diff = new Date(value).getTime() - Date.now()
      const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" })
      const abs = Math.abs(diff)
      if (abs < 3_600_000) return rtf.format(Math.round(diff / 60_000), "minute")
      if (abs < DAY) return rtf.format(Math.round(diff / 3_600_000), "hour")
      if (abs < 7 * DAY) return rtf.format(Math.round(diff / DAY), "day")
      if (abs < 30 * DAY) return rtf.format(Math.round(diff / (7 * DAY)), "week")
      return rtf.format(Math.round(diff / (30 * DAY)), "month")
    },
  }
}

