/** Plugin signals marked as tiles, as tiles. */
function signalTiles(
  items: Array<{ provider: SignalProvider; signal: Signal }>,
  label: (p: SignalProvider) => string
): Tile[] {
  return items
    .filter(({ signal }) => signal.tile)
    .map(({ provider, signal }) => ({
      key: `${provider.id}:${signal.key}`,
      label: signal.tile!.label,
      hint: signal.tile!.hint ?? label(provider),
      count: signal.count ?? null,
      level: signal.level,
      rows: signal.href ? [<ListRow key="open" to={signal.href} title={signal.text} subtitle={label(provider)} />] : [],
    }))
}

