const LATEST = 50
const PAID = ["captured", "partially_captured", "authorized", "partially_authorized", "partially_refunded"]
const UNPAID = ["not_paid", "awaiting", "requires_action"]
const CLOSED = ["canceled", "draft", "archived"]

function useLatestOrders(enabled: boolean) {
  return useQuery({
    queryKey: ["bitshaft-overview", "orders", LATEST],
    queryFn: () =>
      fetchJson<{ orders: Row[]; count: number }>("/admin/orders", {
        limit: LATEST,
        order: "-created_at",
        fields:
          "id,display_id,status,created_at,email,payment_status,fulfillment_status,total,currency_code,shipping_methods.name",
      }),
    enabled,
    staleTime: STALE,
  })
}

