/* Products: stock and sales ---------------------------------------------------- */

const PRODUCT_FIELDS =
  "id,title,status,thumbnail,handle,updated_at,created_at,images.id,variants.id,variants.title,variants.sku,variants.weight,variants.manage_inventory,*variants.prices,*variants.inventory_items,*variants.inventory_items.inventory.location_levels"

/** What can be sold now: per variant the scarcest inventory item, over every location. */
export function stockOf(product: Row): { available: number; reserved: number; tracked: boolean } {
  let available = 0
  let reserved = 0
  let tracked = false
  for (const variant of product.variants ?? []) {
    if (!variant?.manage_inventory) continue
    tracked = true
    const items = (variant.inventory_items ?? []).filter(Boolean)
    if (!items.length) continue
    let variantAvailable = Infinity
    for (const item of items) {
      const levels = (item.inventory?.location_levels ?? []).filter(Boolean)
      const free = levels.reduce((sum: number, l: Row) => sum + Number(l.available_quantity ?? 0), 0)
      reserved += levels.reduce((sum: number, l: Row) => sum + Number(l.reserved_quantity ?? 0), 0)
      variantAvailable = Math.min(variantAvailable, Math.floor(free / Math.max(1, Number(item.required_quantity ?? 1))))
    }
    available += Number.isFinite(variantAvailable) ? Math.max(0, variantAvailable) : 0
  }
  return { available, reserved, tracked }
}

type Sales = {
  qty30: number
  value30: number
  qty90: number
  orders90: number
  value90: number
  last: string | null
  currency: string | null
}

const SALES_ORDERS = 500

/** Sales per product from the orders of the last 90 days (at most SALES_ORDERS). */
function useSales(enabled: boolean) {
  return useQuery({
    queryKey: ["bitshaft-overview", "sales", 90],
    queryFn: async () => {
      const since = new Date(Date.now() - 90 * DAY).toISOString()
      const result = await fetchAll(
        "/admin/orders",
        "orders",
        {
          order: "-created_at",
          "created_at[$gte]": since,
          fields: "id,created_at,status,currency_code,items.product_id,items.quantity,items.total,items.unit_price",
        },
        SALES_ORDERS
      )
      const byProduct: Record<string, Sales> = {}
      for (const order of result.rows) {
        if (["canceled", "draft"].includes(order.status)) continue
        const recent = Date.now() - new Date(order.created_at).getTime() < 30 * DAY
        const seen = new Set<string>()
        for (const item of (order.items ?? []).filter(Boolean)) {
          if (!item.product_id) continue
          const s = (byProduct[item.product_id] ??= {
            qty30: 0,
            value30: 0,
            qty90: 0,
            orders90: 0,
            value90: 0,
            last: null,
            currency: order.currency_code ?? null,
          })
          const qty = Number(item.quantity ?? 0)
          const value = Number(item.total ?? Number(item.unit_price ?? 0) * qty)
          s.qty90 += qty
          s.value90 += value
          if (recent) {
            s.qty30 += qty
            s.value30 += value
          }
          if (!seen.has(item.product_id)) {
            seen.add(item.product_id)
            s.orders90 += 1
          }
          if (!s.last || order.created_at > s.last) s.last = order.created_at
        }
      }
      return { byProduct, orders: result.rows.length, capped: result.capped }
    },
    enabled,
    staleTime: STALE,
  })
}

/* Catalog ---------------------------------------------------------------------- */

const CATALOG_PRODUCTS = 500

/** "Catalog at a glance" above Medusa's product list; `owner` is the calling plugin's namespace. */
export const CatalogOverview = ({ owner }: { owner: string }) =>
  isOwner(OVERVIEW_ZONES.catalog, owner) ? <CatalogCard /> : null

const CatalogCard = () => {
  const k = useKitText()
  const f = useFormat()
  const [settings, save] = useCardSettings()
  const collapsed = Boolean(settings.collapsed.catalog)
  const products = useQuery({
    queryKey: ["bitshaft-overview", "catalog", CATALOG_PRODUCTS],
    queryFn: () =>
      fetchAll("/admin/products", "products", { fields: PRODUCT_FIELDS, order: "-updated_at" }, CATALOG_PRODUCTS),
    enabled: !collapsed,
    staleTime: STALE,
  })
  const sales = useSales(!collapsed)
  const signals = useSignals("catalog", {})
  const [selected, setSelected] = useState("bestSellers")
  const [editing, setEditing] = useState(false)

  const list = products.data?.rows ?? []
  const salesOf = (id: string) => sales.data?.byProduct[id]
  const stock = (p: Row) => stockOf(p)
  const published = list.filter((p) => p.status === "published")
  const groups: Record<string, Row[]> = {
    outOfStock: published.filter((p) => stock(p).tracked && stock(p).available <= 0),
    lowStock: published.filter((p) => {
      const s = stock(p)
      return s.tracked && s.available > 0 && s.available <= settings.lowStock
    }),
    shelf: published.filter((p) => {
      const s = stock(p)
      const last = salesOf(p.id)?.last
      const old = Date.now() - new Date(p.created_at).getTime() > settings.shelfDays * DAY
      return s.available > 0 && old && (!last || Date.now() - new Date(last).getTime() > settings.shelfDays * DAY)
    }),
    drafts: list.filter((p) => p.status === "draft"),
    noImages: list.filter((p) => !p.thumbnail && !(p.images ?? []).length),
    bestSellers: list
      .filter((p) => (salesOf(p.id)?.qty30 ?? 0) > 0)
      .sort((a, b) => (salesOf(b.id)?.qty30 ?? 0) - (salesOf(a.id)?.qty30 ?? 0)),
  }
  const productRow = (p: Row) => {
    const s = stock(p)
    const sale = salesOf(p.id)
    return (
      <ListRow
        key={p.id}
        to={`/products/${p.id}`}
        thumbnail={p.thumbnail ?? null}
        title={p.title}
        subtitle={s.tracked ? k("available", { available: s.available, reserved: s.reserved }) : k("unlimited")}
        aside={
          sale && sale.qty30 > 0 ? (
            <Text size="xsmall" className="text-ui-fg-subtle">
              {k("sales30", { qty: sale.qty30, value: f.money(sale.value30, sale.currency ?? "pln") })}
            </Text>
          ) : undefined
        }
      />
    )
  }
  const tile = (key: string, labelKey: KitTextKey, hint: string, level: Level): Tile => ({
    key,
    label: k(labelKey),
    hint,
    count: products.data ? groups[key].length : null,
    level,
    rows: groups[key].slice(0, 10).map(productRow),
  })
  const tiles: Tile[] = [
    tile("outOfStock", "outOfStock", k("outOfStockHint"), "error"),
    tile("lowStock", "lowStock", k("lowStockHint", { threshold: settings.lowStock }), "warn"),
    tile("shelf", "shelf", k("shelfHint", { days: settings.shelfDays }), "info"),
    tile("drafts", "drafts", k("draftsHint"), "none"),
    tile("noImages", "noImages", k("noImagesHint"), "warn"),
    tile("bestSellers", "bestSellers", k("bestSellersHint"), "ok"),
  ]
  const active = tiles.find((t) => t.key === selected) ?? tiles[0]

  return (
    <Container className="overflow-hidden divide-y p-0">
      <CardHeader
        title={k("catalogTitle")}
        collapsed={collapsed}
        onToggle={() => save({ ...settings, collapsed: { ...settings.collapsed, catalog: !collapsed } })}
        badges={
          products.data && (
            <Badge size="2xsmall">
              {products.data.capped
                ? k("productsCapped", { count: list.length })
                : k("products", { count: products.data.count })}
            </Badge>
          )
        }
      >
        {!collapsed && (
          <Button size="small" variant="transparent" onClick={() => setEditing(!editing)}>
            {k("thresholds")}
          </Button>
        )}
      </CardHeader>
      {!collapsed && editing && (
        <Thresholds
          settings={settings}
          onSave={(next) => {
            save(next)
            setEditing(false)
          }}
        />
      )}
      {!collapsed && (
        <>
          {products.isLoading ? (
            <Skeleton className="m-6 h-20" />
          ) : (
            <Tiles tiles={tiles} selected={active.key} onSelect={setSelected} />
          )}
          {!products.isLoading && (
            <div className="divide-y">
              {active.rows?.length ? (
                active.rows
              ) : (
                <Text size="small" className="px-6 py-4 text-ui-fg-subtle">
                  {k("noneHere")}
                </Text>
              )}
            </div>
          )}
          {sales.data?.capped && (
            <Text size="xsmall" className="px-6 py-2 text-ui-fg-muted">
              {k("salesWindow", { count: sales.data.orders })}
            </Text>
          )}
          <SignalStrip title={k("integrations")} items={signals} />
        </>
      )}
    </Container>
  )
}

const Thresholds = ({ settings, onSave }: { settings: CardSettings; onSave: (next: CardSettings) => void }) => {
  const k = useKitText()
  const [low, setLow] = useState(String(settings.lowStock))
  const [days, setDays] = useState(String(settings.shelfDays))
  const lowValue = Number(low)
  const daysValue = Number(days)
  const valid = Number.isInteger(lowValue) && lowValue >= 0 && Number.isInteger(daysValue) && daysValue >= 1
  return (
    <div className="flex flex-wrap items-end gap-4 px-6 py-4">
      <div className="flex flex-col gap-y-1">
        <Label size="xsmall" weight="plus" htmlFor="bitshaft-low-stock">
          {k("lowThreshold")}
        </Label>
        <Input
          id="bitshaft-low-stock"
          size="small"
          type="number"
          min={0}
          className="w-28"
          value={low}
          onChange={(e) => setLow(e.target.value)}
        />
      </div>
      <div className="flex flex-col gap-y-1">
        <Label size="xsmall" weight="plus" htmlFor="bitshaft-shelf-days">
          {k("shelfDays")}
        </Label>
        <Input
          id="bitshaft-shelf-days"
          size="small"
          type="number"
          min={1}
          className="w-28"
          value={days}
          onChange={(e) => setDays(e.target.value)}
        />
      </div>
      <Button
        size="small"
        disabled={!valid}
        onClick={() => onSave({ ...settings, lowStock: lowValue, shelfDays: daysValue })}
      >
        {k("save")}
      </Button>
    </div>
  )
}

